/**
 * browser-skills storage tests — covers the 3-tier walk, frontmatter parsing,
 * tombstone semantics. Uses tmp dirs for hermetic isolation; never touches
 * real ~/.gstack/ or the gstack install.
 */

import { describe, it, expect, beforeEach, afterEach } from 'bun:test';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import {
  parseSkillFile,
  listBrowserSkills,
  readBrowserSkill,
  tombstoneBrowserSkill,
  type TierPaths,
} from '../src/browser-skills';

let tmpRoot: string;
let tiers: TierPaths;

beforeEach(() => {
  tmpRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'browser-skills-test-'));
  tiers = {
    project: path.join(tmpRoot, 'project', '.gstack', 'browser-skills'),
    global: path.join(tmpRoot, 'home', '.gstack', 'browser-skills'),
    bundled: path.join(tmpRoot, 'gstack-install', 'browser-skills'),
  };
  fs.mkdirSync(tiers.project!, { recursive: true });
  fs.mkdirSync(tiers.global, { recursive: true });
  fs.mkdirSync(tiers.bundled, { recursive: true });
});

afterEach(() => {
  fs.rmSync(tmpRoot, { recursive: true, force: true });
});

function makeSkill(tierRoot: string, name: string, frontmatter: string, body: string = '\nBody.\n') {
  const dir = path.join(tierRoot, name);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, 'SKILL.md'), `---\n${frontmatter}\n---\n${body}`);
  return dir;
}

describe('parseSkillFile', () => {
  it('parses simple frontmatter scalars', () => {
    const md = '---\nname: foo\nhost: example.com\ndescription: hello world\ntrusted: true\n---\nbody';
    const { frontmatter, bodyMd } = parseSkillFile(md);
    expect(frontmatter.name).toBe('foo');
    expect(frontmatter.host).toBe('example.com');
    expect(frontmatter.description).toBe('hello world');
    expect(frontmatter.trusted).toBe(true);
    expect(bodyMd).toBe('body');
  });

  it('parses string lists', () => {
    const md = `---
name: foo
host: example.com
triggers:
  - first trigger
  - second trigger
  - "with: colons"
---
body`;
    const { frontmatter } = parseSkillFile(md);
    expect(frontmatter.triggers).toEqual(['first trigger', 'second trigger', 'with: colons']);
  });

  it('parses args list of mappings', () => {
    const md = `---
name: foo
host: example.com
args:
  - name: keywords
    description: search query
  - name: limit
    description: max results
---`;
    const { frontmatter } = parseSkillFile(md);
    expect(frontmatter.args).toEqual([
      { name: 'keywords', description: 'search query' },
      { name: 'limit', description: 'max results' },
    ]);
  });

  it('handles empty inline list', () => {
    const md = '---\nname: foo\nhost: example.com\nargs: []\ntriggers: []\n---\n';
    const { frontmatter } = parseSkillFile(md);
    expect(frontmatter.args).toEqual([]);
    expect(frontmatter.triggers).toEqual([]);
  });

  it('defaults trusted to false', () => {
    const md = '---\nname: foo\nhost: example.com\n---\n';
    const { frontmatter } = parseSkillFile(md);
    expect(frontmatter.trusted).toBe(false);
  });

  it('throws when frontmatter is missing', () => {
    expect(() => parseSkillFile('no frontmatter here')).toThrow(/missing frontmatter/);
  });

  it('throws when frontmatter terminator is missing', () => {
    expect(() => parseSkillFile('---\nname: foo\nhost: bar\n')).toThrow(/not terminated/);
  });

  it('throws when host is missing', () => {
    const md = '---\nname: foo\n---\nbody';
    expect(() => parseSkillFile(md)).toThrow(/missing required field: host/);
  });

  it('throws when name is absent and no skillName hint', () => {
    const md = '---\nhost: x\n---\nbody';
    expect(() => parseSkillFile(md)).toThrow(/missing required field: name/);
  });

  it('uses skillName hint when frontmatter omits name', () => {
    const md = '---\nhost: example.com\n---\nbody';
    const { frontmatter } = parseSkillFile(md, { skillName: 'derived-name' });
    expect(frontmatter.name).toBe('derived-name');
  });

  it('parses source field as union', () => {
    const human = parseSkillFile('---\nname: f\nhost: h\nsource: human\n---\n').frontmatter;
    const agent = parseSkillFile('---\nname: f\nhost: h\nsource: agent\n---\n').frontmatter;
    const bogus = parseSkillFile('---\nname: f\nhost: h\nsource: alien\n---\n').frontmatter;
    expect(human.source).toBe('human');
    expect(agent.source).toBe('agent');
    expect(bogus.source).toBeUndefined();
  });
});

describe('listBrowserSkills', () => {
  it('returns empty when no tiers have skills', () => {
    expect(listBrowserSkills(tiers)).toEqual([]);
  });

  it('returns bundled-tier skills', () => {
    makeSkill(tiers.bundled, 'foo', 'name: foo\nhost: example.com');
    const skills = listBrowserSkills(tiers);
    expect(skills).toHaveLength(1);
    expect(skills[0].name).toBe('foo');
    expect(skills[0].tier).toBe('bundled');
  });

  it('returns global-tier skills', () => {
    makeSkill(tiers.global, 'bar', 'name: bar\nhost: example.com');
    const skills = listBrowserSkills(tiers);
    expect(skills).toHaveLength(1);
    expect(skills[0].tier).toBe('global');
  });

  it('returns project-tier skills', () => {
    makeSkill(tiers.project!, 'baz', 'name: baz\nhost: example.com');
    const skills = listBrowserSkills(tiers);
    expect(skills).toHaveLength(1);
    expect(skills[0].tier).toBe('project');
  });

  it('global overrides bundled when same name', () => {
    makeSkill(tiers.bundled, 'shared', 'name: shared\nhost: bundled.com');
    makeSkill(tiers.global, 'shared', 'name: shared\nhost: global.com');
    const skills = listBrowserSkills(tiers);
    expect(skills).toHaveLength(1);
    expect(skills[0].tier).toBe('global');
    expect(skills[0].frontmatter.host).toBe('global.com');
  });

  it('project overrides global and bundled when same name', () => {
    makeSkill(tiers.bundled, 'shared', 'name: shared\nhost: bundled.com');
    makeSkill(tiers.global, 'shared', 'name: shared\nhost: global.com');
    makeSkill(tiers.project!, 'shared', 'name: shared\nhost: project.com');
    const skills = listBrowserSkills(tiers);
    expect(skills).toHaveLength(1);
    expect(skills[0].tier).toBe('project');
    expect(skills[0].frontmatter.host).toBe('project.com');
  });

  it('returns all unique skills across tiers, sorted alphabetically', () => {
    makeSkill(tiers.bundled, 'zebra', 'name: zebra\nhost: x.com');
    makeSkill(tiers.global, 'apple', 'name: apple\nhost: x.com');
    makeSkill(tiers.project!, 'mango', 'name: mango\nhost: x.com');
    const skills = listBrowserSkills(tiers);
    expect(skills.map(s => s.name)).toEqual(['apple', 'mango', 'zebra']);
    expect(skills.map(s => s.tier)).toEqual(['global', 'project', 'bundled']);
  });

  it('skips entries without SKILL.md', () => {
    fs.mkdirSync(path.join(tiers.bundled, 'no-skill-md'));
    fs.writeFileSync(path.join(tiers.bundled, 'no-skill-md', 'README'), 'nothing here');
    expect(listBrowserSkills(tiers)).toEqual([]);
  });

  it('skips dotfiles and .tombstones', () => {
    makeSkill(tiers.bundled, '.hidden', 'name: hidden\nhost: x.com');
    fs.mkdirSync(path.join(tiers.global, '.tombstones', 'old-skill'), { recursive: true });
    fs.writeFileSync(path.join(tiers.global, '.tombstones', 'old-skill', 'SKILL.md'), '---\nname: x\nhost: y\n---\n');
    expect(listBrowserSkills(tiers)).toEqual([]);
  });

  it('skips malformed SKILL.md silently (best-effort listing)', () => {
    fs.mkdirSync(path.join(tiers.bundled, 'broken'));
    fs.writeFileSync(path.join(tiers.bundled, 'broken', 'SKILL.md'), 'no frontmatter');
    makeSkill(tiers.bundled, 'good', 'name: good\nhost: x.com');
    const skills = listBrowserSkills(tiers);
    expect(skills.map(s => s.name)).toEqual(['good']);
  });
});

describe('readBrowserSkill', () => {
  it('returns null when skill missing in all tiers', () => {
    expect(readBrowserSkill('nope', tiers)).toBeNull();
  });

  it('finds bundled-tier skill', () => {
    makeSkill(tiers.bundled, 'foo', 'name: foo\nhost: example.com');
    const skill = readBrowserSkill('foo', tiers);
    expect(skill).not.toBeNull();
    expect(skill!.tier).toBe('bundled');
  });

  it('returns project-tier when same name in all three', () => {
    makeSkill(tiers.bundled, 'shared', 'name: shared\nhost: bundled.com');
    makeSkill(tiers.global, 'shared', 'name: shared\nhost: global.com');
    makeSkill(tiers.project!, 'shared', 'name: shared\nhost: project.com');
    const skill = readBrowserSkill('shared', tiers);
    expect(skill!.tier).toBe('project');
    expect(skill!.frontmatter.host).toBe('project.com');
  });

  it('falls through to bundled when global is malformed', () => {
    makeSkill(tiers.bundled, 'foo', 'name: foo\nhost: bundled.com');
    fs.mkdirSync(path.join(tiers.global, 'foo'));
    fs.writeFileSync(path.join(tiers.global, 'foo', 'SKILL.md'), 'malformed');
    const skill = readBrowserSkill('foo', tiers);
    expect(skill!.tier).toBe('bundled');
    expect(skill!.frontmatter.host).toBe('bundled.com');
  });

  it('reads bodyMd correctly', () => {
    makeSkill(tiers.bundled, 'foo', 'name: foo\nhost: x.com', '\n# Heading\n\nProse.\n');
    const skill = readBrowserSkill('foo', tiers);
    expect(skill!.bodyMd).toContain('# Heading');
    expect(skill!.bodyMd).toContain('Prose.');
  });
});

describe('tombstoneBrowserSkill', () => {
  it('moves a global-tier skill to .tombstones/', () => {
    makeSkill(tiers.global, 'gone', 'name: gone\nhost: x.com');
    const dst = tombstoneBrowserSkill('gone', 'global', tiers);
    expect(fs.existsSync(path.join(tiers.global, 'gone'))).toBe(false);
    expect(fs.existsSync(dst)).toBe(true);
    expect(dst).toContain('.tombstones');
  });

  it('moves a project-tier skill to .tombstones/', () => {
    makeSkill(tiers.project!, 'gone', 'name: gone\nhost: x.com');
    const dst = tombstoneBrowserSkill('gone', 'project', tiers);
    expect(fs.existsSync(path.join(tiers.project!, 'gone'))).toBe(false);
    expect(fs.existsSync(dst)).toBe(true);
  });

  it('after tombstone, listBrowserSkills no longer returns it', () => {
    makeSkill(tiers.global, 'gone', 'name: gone\nhost: x.com');
    expect(listBrowserSkills(tiers)).toHaveLength(1);
    tombstoneBrowserSkill('gone', 'global', tiers);
    expect(listBrowserSkills(tiers)).toEqual([]);
  });

  it('throws when skill not found in target tier', () => {
    expect(() => tombstoneBrowserSkill('nope', 'global', tiers)).toThrow(/not found/);
  });

  it('after tombstone, listBrowserSkills falls through to bundled', () => {
    makeSkill(tiers.bundled, 'shared', 'name: shared\nhost: bundled.com');
    makeSkill(tiers.global, 'shared', 'name: shared\nhost: global.com');
    expect(listBrowserSkills(tiers)[0].tier).toBe('global');
    tombstoneBrowserSkill('shared', 'global', tiers);
    expect(listBrowserSkills(tiers)[0].tier).toBe('bundled');
  });
});

/**
 * scripts/update-readme-throughput.ts + README anchor + CI pending-marker gate.
 *
 * Coverage:
 * - Happy path: JSON present, anchor gets replaced with number + anchor preserved
 * - Missing JSON: script writes PENDING marker, CI would reject
 * - Invalid JSON: script errors, README untouched
 * - CI gate: committed README must not contain PENDING marker
 */
import { describe, test, expect, beforeEach, afterEach } from 'bun:test';
import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';
import { spawnSync } from 'child_process';

const ROOT = path.resolve(import.meta.dir, '..');
const SCRIPT = path.join(ROOT, 'scripts', 'update-readme-throughput.ts');

const ANCHOR = '<!-- GSTACK-THROUGHPUT-PLACEHOLDER -->';
const PENDING = 'GSTACK-THROUGHPUT-PENDING';

let tmpDir: string;
let tmpReadme: string;
let tmpJsonPath: string;

beforeEach(() => {
  tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'gstack-readme-test-'));
  tmpReadme = path.join(tmpDir, 'README.md');
  fs.mkdirSync(path.join(tmpDir, 'docs'), { recursive: true });
  tmpJsonPath = path.join(tmpDir, 'docs', 'throughput-2013-vs-2026.json');
});

afterEach(() => {
  fs.rmSync(tmpDir, { recursive: true, force: true });
});

function runScript(cwd: string): { stdout: string; stderr: string; status: number } {
  const res = spawnSync('bun', ['run', SCRIPT], {
    encoding: 'utf-8',
    cwd,
    env: { ...process.env },
  });
  return {
    stdout: (res.stdout ?? '').trim(),
    stderr: (res.stderr ?? '').trim(),
    status: res.status ?? -1,
  };
}

describe('update-readme-throughput script', () => {
  test('happy path: JSON present → anchor replaced with number', () => {
    fs.writeFileSync(tmpReadme, `gstack hero: ${ANCHOR} 2013 pro-rata.\n`);
    fs.writeFileSync(tmpJsonPath, JSON.stringify({
      multiples: { logical_lines_added: 12.3 },
    }));

    const result = runScript(tmpDir);
    expect(result.status).toBe(0);

    const updated = fs.readFileSync(tmpReadme, 'utf-8');
    expect(updated).toContain('12.3×');
    expect(updated).toContain(ANCHOR); // anchor stays for next run
    expect(updated).not.toContain(PENDING);
  });

  test('missing JSON: PENDING marker written (CI rejects)', () => {
    fs.writeFileSync(tmpReadme, `gstack hero: ${ANCHOR} 2013 pro-rata.\n`);
    // No JSON written

    const result = runScript(tmpDir);
    expect(result.status).toBe(0);

    const updated = fs.readFileSync(tmpReadme, 'utf-8');
    expect(updated).toContain(PENDING);
    expect(updated).toContain(ANCHOR); // anchor preserved for next run
  });

  test('JSON with null multiple: PENDING marker written (honest missing state)', () => {
    fs.writeFileSync(tmpReadme, `gstack hero: ${ANCHOR} 2013 pro-rata.\n`);
    fs.writeFileSync(tmpJsonPath, JSON.stringify({
      multiples: { logical_lines_added: null },
    }));

    const result = runScript(tmpDir);
    expect(result.status).toBe(0);

    const updated = fs.readFileSync(tmpReadme, 'utf-8');
    expect(updated).toContain(PENDING);
    expect(updated).not.toMatch(/null×/);
  });

  test('anchor already replaced: script is a no-op', () => {
    fs.writeFileSync(tmpReadme, 'gstack hero: 7.0× already set.\n');
    // No anchor in README → nothing to replace

    const result = runScript(tmpDir);
    expect(result.status).toBe(0);

    const updated = fs.readFileSync(tmpReadme, 'utf-8');
    expect(updated).toBe('gstack hero: 7.0× already set.\n');
  });
});

describe('CI gate: committed README must not contain PENDING marker', () => {
  // This is the core reason the PENDING marker exists. A commit that lands
  // the README with the pending string means the build didn't run.
  test('real README.md does not contain GSTACK-THROUGHPUT-PENDING', () => {
    const readmePath = path.join(ROOT, 'README.md');
    if (!fs.existsSync(readmePath)) return; // Fresh clone edge-case
    const content = fs.readFileSync(readmePath, 'utf-8');
    expect(content).not.toContain(PENDING);
  });
});

/**
 * Preamble composition order — gate-tier test.
 *
 * Asserts that the AskUserQuestion Format section renders BEFORE the
 * Model-Specific Behavioral Patch section in tier-≥2 preamble output.
 * This order is load-bearing: Opus 4.7 reads top-to-bottom and absorbs
 * the first pacing directive it hits. v1.6.4.0 regressed plan-review
 * cadence because the overlay rendered first with "Batch your questions"
 * as the ambient default.
 *
 * If someone later reorders `scripts/resolvers/preamble.ts` so Overlay
 * comes before Format, this test catches it before the next model
 * migration can silently re-break the plan-review pacing.
 */
import { describe, test, expect } from 'bun:test';
import type { TemplateContext } from '../scripts/resolvers/types';
import { HOST_PATHS } from '../scripts/resolvers/types';
import { generatePreamble } from '../scripts/resolvers/preamble';

function makeCtx(
  host: 'claude' | 'codex',
  tier: 1 | 2 | 3 | 4,
  model?: string,
): TemplateContext {
  return {
    skillName: 'test-skill',
    tmplPath: 'test.tmpl',
    host,
    paths: HOST_PATHS[host],
    preambleTier: tier,
    ...(model ? { model } : {}),
  };
}

describe('Preamble composition order', () => {
  test('AskUserQuestion Format renders before Model-Specific Behavioral Patch (tier 2, claude)', () => {
    const out = generatePreamble(makeCtx('claude', 2, 'claude'));
    const formatIdx = out.indexOf('## AskUserQuestion Format');
    const overlayIdx = out.indexOf('## Model-Specific Behavioral Patch');
    expect(formatIdx).toBeGreaterThan(-1);
    expect(overlayIdx).toBeGreaterThan(-1);
    expect(formatIdx).toBeLessThan(overlayIdx);
  });

  test('AskUserQuestion Format renders before Model-Specific Behavioral Patch (tier 2, opus-4-7)', () => {
    const out = generatePreamble(makeCtx('claude', 2, 'opus-4-7'));
    const formatIdx = out.indexOf('## AskUserQuestion Format');
    const overlayIdx = out.indexOf('## Model-Specific Behavioral Patch');
    expect(formatIdx).toBeGreaterThan(-1);
    expect(overlayIdx).toBeGreaterThan(-1);
    expect(formatIdx).toBeLessThan(overlayIdx);
  });

  test('AskUserQuestion Format renders before Model-Specific Behavioral Patch (tier 3)', () => {
    const out = generatePreamble(makeCtx('claude', 3, 'opus-4-7'));
    const formatIdx = out.indexOf('## AskUserQuestion Format');
    const overlayIdx = out.indexOf('## Model-Specific Behavioral Patch');
    expect(formatIdx).toBeLessThan(overlayIdx);
  });

  test('AskUserQuestion Format renders before Model-Specific Behavioral Patch (codex host)', () => {
    const out = generatePreamble(makeCtx('codex', 2, 'opus-4-7'));
    const formatIdx = out.indexOf('## AskUserQuestion Format');
    const overlayIdx = out.indexOf('## Model-Specific Behavioral Patch');
    expect(formatIdx).toBeLessThan(overlayIdx);
  });

  test('tier 1 preamble does NOT include AskUserQuestion Format (but MAY include overlay)', () => {
    const out = generatePreamble(makeCtx('claude', 1));
    expect(out).not.toContain('## AskUserQuestion Format');
  });
});

describe('Conductor signal (preamble bash)', () => {
  test('claude preamble emits CONDUCTOR_SESSION, gated on != headless (Issue 8)', () => {
    const out = generatePreamble(makeCtx('claude', 2, 'claude'));
    expect(out).toContain('echo "CONDUCTOR_SESSION: true"');
    // The emission must be suppressed when the session is headless (eval/CI
    // inside Conductor must BLOCK, not render prose to nobody).
    expect(out).toMatch(/"\$_SESSION_KIND" != "headless"[\s\S]*CONDUCTOR_WORKSPACE_PATH[\s\S]*CONDUCTOR_PORT[\s\S]*CONDUCTOR_SESSION: true/);
  });
});

/**
 * Global test preload (Bun: `[test] preload` in bunfig.toml).
 *
 * Snapshots `process.env` once at preload time, then restores it after
 * every test. Defends against the recurring pollution class where one
 * test file mutates `process.env.PATH` / `HOME` / etc. and leaks into
 * unrelated subsequent files in the same Bun process — surfaces as
 * `Executable not found in $PATH: "bun"` or `Bun.which('bash')` returning
 * null in tests that have no business touching env.
 *
 * `process.env = X` reassignment does work in Bun (it swaps the underlying
 * proxy), but several test files use the broken pattern of
 * `origEnv = {...process.env}` followed by per-test mutation without a
 * matching restore inside try/finally. Centralizing the safety net here
 * means new tests don't have to remember the dance, and the bug class
 * stays dead.
 */
import { afterEach, beforeAll } from 'bun:test';

// Narrowly restore PATH after every test. Defends against the recurring
// pollution class where one test sets `process.env.PATH = '/test/bin:/usr/bin'`
// to exercise a scrubbed-env fixture and either forgets to restore or uses
// the broken `process.env = origEnv` reassignment, then a downstream test
// (security.test.ts > resolveBashBinary, pair-agent-tunnel-eval, or
// server-no-import-side-effects) sees the wrong PATH and either has
// `Bun.which('bash')` return null or `Bun.spawn(['bun', ...])` ENOENT.
//
// Deliberately narrow: snapshotting + restoring all of process.env breaks
// tests that legitimately set per-file env at module top-level (e.g.,
// domain-skills-storage.test.ts assigns `process.env.GSTACK_HOME` at
// import time so the loaded module reads the test sandbox path on first
// invocation — wiping that on afterEach would route reads at the user's
// real ~/.gstack and the test would assert on the wrong filesystem).
//
// If a future test pollutes a different variable in the same broken way,
// add it to RESTORE_KEYS rather than widening the snapshot scope.
const RESTORE_KEYS = ['PATH', 'Path'] as const;
const baseline: Record<string, string | undefined> = {};

beforeAll(() => {
  for (const k of RESTORE_KEYS) baseline[k] = process.env[k];
});

afterEach(() => {
  for (const k of RESTORE_KEYS) {
    const want = baseline[k];
    if (want === undefined) {
      if (process.env[k] !== undefined) delete process.env[k];
    } else if (process.env[k] !== want) {
      process.env[k] = want;
    }
  }
});

import { describe, test, expect, beforeAll, afterAll } from 'bun:test';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { execSync } from 'child_process';

// Regression guard for the conductor/workspace setup hang:
// `./setup` used a blocking `read -r` to ask "Install both hooks now? [y/N]".
// When setup runs under a forwarded/automated TTY (conductor workspace setup,
// CI with a pty) the read blocked forever. The fix moves the decision into
// flags + env + saved config with a non-blocking, time-bounded prompt fallback.
//
// These are static + binary-level assertions (free, <1s) — they lock in the
// contract without running the full (environment-mutating) setup script.

const ROOT = path.resolve(import.meta.dir, '..');
const SETUP = path.join(ROOT, 'setup');
const GSTACK_CONFIG = path.join(ROOT, 'bin', 'gstack-config');

const setupSrc = fs.readFileSync(SETUP, 'utf-8');

describe('setup: plan-tune hooks are non-interactive-safe', () => {
  test('exposes --plan-tune-hooks / --no-plan-tune-hooks / =value flags', () => {
    expect(setupSrc).toContain('--plan-tune-hooks)');
    expect(setupSrc).toContain('--no-plan-tune-hooks)');
    expect(setupSrc).toContain('--plan-tune-hooks=*)');
  });

  test('resolution falls through env then saved config', () => {
    expect(setupSrc).toContain('GSTACK_PLAN_TUNE_HOOKS');
    expect(setupSrc).toContain('get plan_tune_hooks');
  });

  test('explicit yes/no decisions never reach a prompt', () => {
    // The yes/no branches must short-circuit before the interactive branch.
    const yesIdx = setupSrc.indexOf('PT_DECISION" = "yes"');
    const noIdx = setupSrc.indexOf('PT_DECISION" = "no"');
    const promptIdx = setupSrc.indexOf('Install both hooks now?');
    expect(yesIdx).toBeGreaterThan(-1);
    expect(noIdx).toBeGreaterThan(-1);
    expect(yesIdx).toBeLessThan(promptIdx);
    expect(noIdx).toBeLessThan(promptIdx);
  });

  test('the interactive prompt is time-bounded (cannot hang)', () => {
    // No bare blocking read for the plan-tune reply.
    expect(setupSrc).not.toMatch(/read -r PLAN_TUNE_INSTALL_REPLY\b/);
    // It must use a timed read from the controlling tty with an empty fallback.
    // The timeout may be a literal or a named variable (e.g. "$_PT_PROMPT_TIMEOUT").
    expect(setupSrc).toMatch(/read -t (?:\d+|"?\$\{?\w+\}?"?) -r PLAN_TUNE_INSTALL_REPLY <\/dev\/tty/);
  });

  test('interactive prompt is gated on a real TTY and non-quiet', () => {
    // The prompt branch requires both stdin+stdout TTYs and not --quiet.
    expect(setupSrc).toMatch(/\[ "\$QUIET" -ne 1 \] && \[ -t 0 \] && \[ -t 1 \]/);
  });

