/**
 * Static invariant: the two install targets that cherry-pick SKILL.md (Claude
 * prefixed dirs + Kiro) must ALSO install the sections/ subdir, or a carved
 * skill's runtime "Read sections/<name>.md" 404s. codex/factory/opencode link
 * the whole generated dir, so sections ride along for free there.
 *
 * Matches the repo's static-tripwire style (setup-windows-fallback,
 * cdp-session-cleanup). End-to-end "sections resolve in a temp install" runs in
 * the group-5/6 functional pass once real ship/sections/ exist.
 */

import { describe, test, expect } from 'bun:test';
import * as fs from 'fs';
import * as path from 'path';

const SETUP = fs.readFileSync(path.join(import.meta.dir, '..', 'setup'), 'utf-8');

/** Body of a shell function `name() { ... }` up to the closing line `}`. */
function fnBody(src: string, name: string): string {
  const start = src.indexOf(`${name}() {`);
  if (start === -1) return '';
  const end = src.indexOf('\n}', start);
  return src.slice(start, end === -1 ? undefined : end);
}

describe('setup links sections/ for cherry-pick install targets', () => {
  test('link_claude_skill_dirs links sections/ via _link_or_copy', () => {
    const body = fnBody(SETUP, 'link_claude_skill_dirs');
    expect(body).toContain('sections');
    // sections install must route through the windows-safe helper, not raw ln.
    expect(body).toMatch(/_link_or_copy\s+"\$gstack_dir\/\$dir_name\/sections"\s+"\$target\/sections"/);
    expect(body).toMatch(/if \[ -d "\$gstack_dir\/\$dir_name\/sections" \]/);
  });

  test('kiro per-skill loop rewrites + copies sections/*', () => {
    // Kiro builds from the codex output and sed-rewrites paths; sections must get
    // the same rewrite so they resolve under ~/.kiro, not ~/.codex or ~/.claude.
    expect(SETUP).toMatch(/if \[ -d "\$skill_dir\/sections" \]/);
    expect(SETUP).toMatch(/mkdir -p "\$target_dir\/sections"/);
    expect(SETUP).toContain('$target_dir/sections/$(basename "$section_file")');
  });

  test('no raw ln introduced (windows-fallback invariant still holds)', () => {
    // Every new line touching sections uses _link_or_copy or sed redirect, never ln.
    const sectionLines = SETUP.split('\n').filter(l => l.includes('sections') && /\bln\s+-/.test(l));
    expect(sectionLines).toEqual([]);
  });
});

import { describe, test, expect } from 'bun:test';
import * as path from 'path';
import * as fs from 'fs';

// Static tripwires for the C (machine-wide) render in `gstack-config
// gbrain-refresh`. The render mutates the shared global install, so the guards
// that stop it from touching the wrong directory are load-bearing — these fail
// CI if any guard is dropped.
const ROOT = path.resolve(import.meta.dir, '..');
const SRC = fs.readFileSync(path.join(ROOT, 'bin', 'gstack-config'), 'utf-8');

// Pull out just the gbrain-refresh `ok)` branch so assertions can't be
// satisfied by unrelated text elsewhere in the file.
function okBranch(): string {
  const start = SRC.indexOf('gbrain-refresh)');
  const ok = SRC.indexOf('ok)', start);
  const end = SRC.indexOf(';;', ok);
  if (start < 0 || ok < 0 || end < 0) throw new Error('Could not locate gbrain-refresh ok) branch');
  return SRC.slice(ok, end);
}

describe('gstack-config gbrain-refresh: machine-wide render guards', () => {
  const branch = okBranch();

  test('targets the global install', () => {
    expect(branch).toContain('$HOME/.claude/skills/gstack');
  });

  test('refuses a symlinked install (would dirty a dev worktree)', () => {
    expect(branch).toMatch(/\[ -L "\$INSTALL_DIR" \]/);
  });

  test('verifies it is a real gstack clone before mutating it', () => {
    expect(branch).toContain('$INSTALL_DIR/VERSION');
    expect(branch).toContain('$INSTALL_DIR/package.json');
  });

  test('requires bun on PATH', () => {
    expect(branch).toContain('command -v bun');
  });

  test('renders the :user variant in place into the install', () => {
    expect(branch).toContain('gen:skill-docs:user --host claude');
  });

  test('is self-documenting about the reset --hard / re-run cycle', () => {
    expect(branch).toContain('reset --hard');
    expect(branch).toContain('gbrain-refresh');
  });
});

describe('CLAUDE.md: deploy section documents the re-run', () => {
  test('notes re-running gbrain-refresh after reset --hard', () => {
    const claudeMd = fs.readFileSync(path.join(ROOT, 'CLAUDE.md'), 'utf-8');
    const idx = claudeMd.indexOf('## Deploying to the active skill');
    expect(idx).toBeGreaterThan(-1);
    const section = claudeMd.slice(idx, idx + 1200);
    expect(section).toContain('gbrain-refresh');
  });
});

/**
 * /document-release + /document-generate redaction wiring (T6/T7).
 */
import { describe, test, expect } from "bun:test";
import * as fs from "fs";
import * as path from "path";

const ROOT = path.resolve(import.meta.dir, "..");
// document-release is carved (skeleton + sections/release-body.md). Step 9
// (commit + PR-body redaction scan) moved into the section template; check the
// union of SKILL.md.tmpl + sections/*.md.tmpl so the scan-before-edit ordering
// still verifies. document-generate is NOT carved (plain .md.tmpl).
function unionTmpl(skill: string): string {
  let t = fs.readFileSync(path.join(ROOT, skill, "SKILL.md.tmpl"), "utf-8");
  const dir = path.join(ROOT, skill, "sections");
  if (fs.existsSync(dir)) {
    for (const f of fs.readdirSync(dir).sort()) {
      if (f.endsWith(".md.tmpl")) t += "\n" + fs.readFileSync(path.join(dir, f), "utf-8");
    }
  }
  return t;
}
const RELEASE = unionTmpl("document-release");
const GENERATE = fs.readFileSync(path.join(ROOT, "document-generate", "SKILL.md.tmpl"), "utf-8");

describe("/document-release redaction", () => {
  test("scans the PR-body temp file before gh pr edit", () => {
    const scanIdx = RELEASE.indexOf("gstack-redact --from-file /tmp/gstack-pr-body");
    const editIdx = RELEASE.indexOf("gh pr edit --body-file /tmp/gstack-pr-body");
    expect(scanIdx).toBeGreaterThan(-1);
    expect(editIdx).toBeGreaterThan(scanIdx);
  });
  test("HIGH blocks the edit", () => {
    expect(RELEASE).toMatch(/exit 3 \(HIGH\).*do NOT edit/i);
  });
});

describe("/document-generate redaction", () => {
  test("scans staged doc diff before commit", () => {
    const scanIdx = GENERATE.indexOf("gstack-redact --repo-visibility");
    const commitIdx = GENERATE.indexOf("git commit -m");
    expect(scanIdx).toBeGreaterThan(-1);
    expect(commitIdx).toBeGreaterThan(scanIdx);
  });
  test("scans added lines of the staged diff", () => {
    expect(GENERATE).toMatch(/git diff --cached[\s\S]{0,80}gstack-redact/);
  });
  test("HIGH blocks the commit", () => {
    expect(GENERATE).toMatch(/Do NOT commit/i);
  });
});

// setup-gbrain Path 4 structural lint.
//
// Verifies the SKILL.md.tmpl has the prose contract that Path 4 (Remote MCP)
// depends on: STOP gates after verify failures, never-write-token rules,
// mode-aware CLAUDE.md block, idempotent re-run path.
//
// Why a structural test instead of a full Agent SDK E2E:
//   - Side effects (claude.json mutation, MCP registration) are covered
//     by unit tests for gstack-gbrain-mcp-verify and gstack-artifacts-init.
//   - The structural prose is the source of regressions for AUQ pacing
//     (the failure mode the gstack repo has tracked since v1.26.x:
//     "wrote_findings_before_asking"). A grep-based regression on the
//     template prose is fast (<200ms), free, and catches the same drift
//     as the paid E2E without spending tokens.
//   - The full Agent SDK E2E remains the right tool for end-to-end
//     pacing eval; this is the gate-tier check that catches the failure
//     class deterministically.

import { describe, test, expect } from 'bun:test';
import * as fs from 'fs';
import * as path from 'path';

const ROOT = path.resolve(import.meta.dir, '..');
const TMPL = path.join(ROOT, 'setup-gbrain', 'SKILL.md.tmpl');

const tmpl = fs.readFileSync(TMPL, 'utf-8');

describe('setup-gbrain Path 4 (Remote MCP) — structural contract', () => {
  test('Step 2 lists Path 4 as one of the path options', () => {
    // "4 — Remote gbrain MCP" with em-dash (—, U+2014 — one codepoint).
    expect(tmpl).toMatch(/\*\*4 . Remote gbrain MCP/);
  });

  test('Step 4 has a Path 4 sub-section', () => {
    expect(tmpl).toMatch(/### Path 4 \(Remote gbrain MCP/);
  });

  test('Step 4 collects the bearer via read_secret_to_env, never argv', () => {
    // The secret-read helper is the canonical token-capture pattern.
    // Without it, tokens land in shell history.
    expect(tmpl).toContain('read_secret_to_env GBRAIN_MCP_TOKEN');
  });

  test('Step 4c invokes gstack-gbrain-mcp-verify and STOPs on failure', () => {
    expect(tmpl).toContain('gstack-gbrain-mcp-verify');
    // The STOP rule is what prevents partial registration after auth fail.
    const path4Section = tmpl.split('### Path 4')[1] || '';
    expect(path4Section).toMatch(/STOP/);
  });

  test('Step 4d explicitly skips Steps 3, 4 (other paths), 5, 7.5 in remote mode', () => {
    expect(tmpl).toMatch(/4d.*[Ss]kip Steps? 3, 4.*5.*7\.5/s);
  });

  test('Step 5a has a Path 4 branch with claude mcp add --transport http', () => {
    expect(tmpl).toMatch(/Path 4 \(Remote MCP/);
    expect(tmpl).toMatch(/claude mcp add --scope user --transport http gbrain/);
    expect(tmpl).toContain('Authorization: Bearer $GBRAIN_MCP_TOKEN');
    // Token must be unset after registration so it doesn't linger in env.
    expect(tmpl).toMatch(/unset GBRAIN_MCP_TOKEN/);
  });

  test('Step 5a removes any prior gbrain registration before adding the new one', () => {
    // Otherwise local-stdio + remote-http coexist, which breaks routing.
    expect(tmpl).toMatch(/claude mcp remove gbrain/);
  });

  test('Step 7 calls gstack-artifacts-init with --url-form-supported flag', () => {
    expect(tmpl).toMatch(/gstack-artifacts-init.*--url-form-supported/);
  });

  test('Step 8 CLAUDE.md block branches on mode', () => {
    // The remote-http block has Mode: remote-http; local-stdio block has Engine:.
    expect(tmpl).toMatch(/### Path 4 \(Remote MCP\)/);
    expect(tmpl).toMatch(/Mode: remote-http/);
    expect(tmpl).toMatch(/Mode: local-stdio/);
  });

  test('Step 8 explicitly says the bearer is never written to CLAUDE.md', () => {
    // Token-leak regression guard. CLAUDE.md is committed in many projects.
    expect(tmpl).toMatch(/bearer token is \*\*never\*\* written to CLAUDE\.md/);
  });

  test('Step 9 smoke test on Path 4 prints a placeholder, never the real token', () => {
    // Don't paste the token into the curl example the user might share.
    expect(tmpl).toMatch(/<YOUR_TOKEN>/);
  });

  test('Step 10 verdict block has a remote-http variant separate from local-stdio', () => {
    expect(tmpl).toMatch(/### Path 4 \(Remote MCP\)/);
    expect(tmpl).toMatch(/mode: remote-http/);
    expect(tmpl).toMatch(/N\/A.*remote mode/);
  });

  test('idempotency: re-running with gbrain_mcp_mode=remote-http skips Step 2', () => {
    // Re-run path stays graceful; no double-registration.
    expect(tmpl).toMatch(/gbrain_mcp_mode=remote-http/);
  });

  test('Step 5 (local doctor) explicitly skips on Path 4', () => {
    expect(tmpl).toMatch(/SKIP entirely on Path 4 \(Remote MCP\)/);
  });

  test('Step 7.5 (transcript ingest) explicitly skips on Path 4', () => {
    // Transcript ingest needs local gbrain CLI which Path 4 doesn't install.
    const matches = tmpl.match(/SKIP entirely on Path 4 \(Remote MCP\)/g);
    expect(matches?.length).toBeGreaterThanOrEqual(2);
  });
});

describe('setup-gbrain Path 4 — token security regressions', () => {
  test('the template never inlines a real-shaped bearer string', () => {
    // We never want a literal "gbrain_<hex>" token to appear in the
    // template — placeholders only. This catches the failure mode where
    // someone copies a real token into the template by accident.
    const realTokenShape = /gbrain_[a-f0-9]{40,}/;
    expect(tmpl).not.toMatch(realTokenShape);
  });

  test('Path 4 always uses env-var $GBRAIN_MCP_TOKEN, never inline strings', () => {
    // Find every reference to the bearer header in Path 4 and verify it's
    // either an env-var expansion or an explicit placeholder. Allow:
    //   - $GBRAIN_MCP_TOKEN  (env-var expansion)
    //   - <bearer>, <YOUR_TOKEN>, <TOKEN>  (placeholder)
    //   - "..."  (rest-of-doc-text continuation; a doc note showing how
    //     `claude mcp add --header` shapes its argv).
    const path4Section = tmpl.match(/### Path 4 \(Remote MCP[\s\S]*?(?=###|## )/g)?.join('') || '';
    const bearerLines = path4Section.match(/Bearer\s+\S+/g) || [];
    for (const line of bearerLines) {
      expect(line).toMatch(/Bearer (\$GBRAIN_MCP_TOKEN|<bearer>|<YOUR_TOKEN>|<TOKEN>|\.\.\."?)/);
    }
  });
});

import { describe, test, expect, beforeEach, afterEach } from 'bun:test';
import { spawnSync } from 'child_process';
import * as fs from 'fs';
