      const result = spawnSync('bash', [UNINSTALL, '--force'], {
        stdio: 'pipe',
        env: {
          ...process.env,
          HOME: cleanHome,
          GSTACK_DIR: path.join(cleanHome, 'nonexistent'),
          GSTACK_STATE_DIR: path.join(cleanHome, '.gstack'),
        },
        cwd: mockGitRoot,
      });

      expect(result.status).toBe(0);
      expect(result.stdout.toString()).toContain('Nothing to remove');
    });

    test('upgrade path: prefixed install + uninstall cleans both old and new symlinks', () => {
      // Simulate the state after setup --no-prefix followed by setup (with prefix):
      // Both old unprefixed and new prefixed symlinks exist
      // (mockHome already has both 'review' and 'gstack-ship' symlinks)

      const result = spawnSync('bash', [UNINSTALL, '--force'], {
        stdio: 'pipe',
        env: {
          ...process.env,
          HOME: mockHome,
          GSTACK_DIR: path.join(mockHome, '.claude', 'skills', 'gstack'),
          GSTACK_STATE_DIR: path.join(mockHome, '.gstack'),
        },
        cwd: mockGitRoot,
      });

      expect(result.status).toBe(0);

      // Both old (review) and new (gstack-ship) symlinks should be gone
      expect(fs.existsSync(path.join(mockHome, '.claude', 'skills', 'review'))).toBe(false);
      expect(fs.existsSync(path.join(mockHome, '.claude', 'skills', 'gstack-ship'))).toBe(false);

      // Non-gstack should survive
      expect(fs.existsSync(path.join(mockHome, '.claude', 'skills', 'other-tool'))).toBe(true);
    });
  });
});

import { describe, test, expect } from 'bun:test';
import { spawnSync } from 'child_process';
import * as path from 'path';
import * as fs from 'fs';
import * as os from 'os';

const ROOT = path.resolve(import.meta.dir, '..');
const SETUP_SCRIPT = path.join(ROOT, 'setup');

describe('setup: Conductor worktree guard', () => {
  test('setup contains the real-dir guard before the symlink-or-copy into ~/.claude/skills/', () => {
    const content = fs.readFileSync(SETUP_SCRIPT, 'utf-8');
    const guardIdx = content.indexOf('_SKIP_CLAUDE_REGISTER=0');
    // v1.36.0.0: symlink work routes through _link_or_copy helper for Windows fallback.
    const lnIdx = content.indexOf('_link_or_copy "$SOURCE_GSTACK_DIR" "$CLAUDE_GSTACK_LINK"');
    expect(guardIdx).toBeGreaterThan(-1);
    expect(lnIdx).toBeGreaterThan(-1);
    expect(guardIdx).toBeLessThan(lnIdx);
  });

  test('guard resolves the existing real dir with `pwd -P` and compares against source', () => {
    const content = fs.readFileSync(SETUP_SCRIPT, 'utf-8');
    expect(content).toContain('[ -d "$CLAUDE_GSTACK_LINK" ] && [ ! -L "$CLAUDE_GSTACK_LINK" ]');
    expect(content).toContain('cd "$CLAUDE_GSTACK_LINK" 2>/dev/null && pwd -P');
    expect(content).toContain('"$_EXISTING_REAL" != "$SOURCE_GSTACK_DIR"');
  });

  test('skip branch prints "registration skipped" + remediation hint', () => {
    const content = fs.readFileSync(SETUP_SCRIPT, 'utf-8');
    expect(content).toContain('Skipping Claude skill registration');
    expect(content).toContain('claude registration skipped');
    expect(content).toContain('rm -rf $CLAUDE_GSTACK_LINK');
  });

  // Reproduce the BSD/macOS `ln -snf` behavior that caused the bug, then
  // confirm the guard avoids it. This is a behavioral test of the guard logic
  // running in an isolated tmpdir — not the full setup script.
  test('BSD ln -snf into an existing real dir creates a child symlink (bug reproduces)', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'gstack-setup-guard-'));
    try {
      const source = path.join(tmp, 'source-worktree');
      const dest = path.join(tmp, 'dest-real-dir');
      fs.mkdirSync(source);
      fs.mkdirSync(dest);
      // The buggy invocation: target dest is an existing real dir.
      const result = spawnSync('ln', ['-snf', source, dest], { encoding: 'utf-8' });
      expect(result.status).toBe(0);
      // Child symlink leaked inside dest.
      const leaked = path.join(dest, path.basename(source));
      expect(fs.existsSync(leaked)).toBe(true);
      expect(fs.lstatSync(leaked).isSymbolicLink()).toBe(true);
      expect(fs.readlinkSync(leaked)).toBe(source);
      // dest itself stayed a real directory (not replaced).
      expect(fs.lstatSync(dest).isSymbolicLink()).toBe(false);
      expect(fs.lstatSync(dest).isDirectory()).toBe(true);
    } finally {
      fs.rmSync(tmp, { recursive: true, force: true });
    }
  });

  test('guard logic refuses to ln when dest is a real dir pointing elsewhere', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'gstack-setup-guard-'));
    try {
      const source = path.join(tmp, 'source-worktree');
      const dest = path.join(tmp, 'dest-real-dir');
      fs.mkdirSync(source);
      fs.mkdirSync(dest);
      // Inline the guard logic from setup. If it triggers, $_SKIP=1 is echoed
      // and no ln is performed; otherwise ln runs and we'd see the leak.
      const script = `
        set -e
        SOURCE_GSTACK_DIR='${source}'
        CLAUDE_GSTACK_LINK='${dest}'
        _SKIP_CLAUDE_REGISTER=0
        if [ -d "$CLAUDE_GSTACK_LINK" ] && [ ! -L "$CLAUDE_GSTACK_LINK" ]; then
          _EXISTING_REAL=$(cd "$CLAUDE_GSTACK_LINK" 2>/dev/null && pwd -P || echo "")
          if [ -n "$_EXISTING_REAL" ] && [ "$_EXISTING_REAL" != "$SOURCE_GSTACK_DIR" ]; then
            _SKIP_CLAUDE_REGISTER=1
          fi
        fi
        if [ "$_SKIP_CLAUDE_REGISTER" -eq 1 ]; then
          echo "SKIP"
        else
          ln -snf "$SOURCE_GSTACK_DIR" "$CLAUDE_GSTACK_LINK"
          echo "LINKED"
        fi
      `;
      const result = spawnSync('bash', ['-c', script], { encoding: 'utf-8' });
      expect(result.status).toBe(0);
      expect(result.stdout.trim()).toBe('SKIP');
      // No child symlink leaked.
      const leaked = path.join(dest, path.basename(source));
      expect(fs.existsSync(leaked)).toBe(false);
    } finally {
      fs.rmSync(tmp, { recursive: true, force: true });
    }
  });

  test('guard allows ln when dest does not exist (fresh install path)', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'gstack-setup-guard-'));
    try {
      const source = path.join(tmp, 'source-worktree');
      const dest = path.join(tmp, 'fresh-dest');
      fs.mkdirSync(source);
      const script = `
        set -e
        SOURCE_GSTACK_DIR='${source}'
        CLAUDE_GSTACK_LINK='${dest}'
        _SKIP_CLAUDE_REGISTER=0
        if [ -d "$CLAUDE_GSTACK_LINK" ] && [ ! -L "$CLAUDE_GSTACK_LINK" ]; then
          _EXISTING_REAL=$(cd "$CLAUDE_GSTACK_LINK" 2>/dev/null && pwd -P || echo "")
          if [ -n "$_EXISTING_REAL" ] && [ "$_EXISTING_REAL" != "$SOURCE_GSTACK_DIR" ]; then
            _SKIP_CLAUDE_REGISTER=1
          fi
        fi
        if [ "$_SKIP_CLAUDE_REGISTER" -eq 1 ]; then
          echo "SKIP"
        else
          ln -snf "$SOURCE_GSTACK_DIR" "$CLAUDE_GSTACK_LINK"
          echo "LINKED"
        fi
      `;
      const result = spawnSync('bash', ['-c', script], { encoding: 'utf-8' });
      expect(result.status).toBe(0);
      expect(result.stdout.trim()).toBe('LINKED');
      expect(fs.lstatSync(dest).isSymbolicLink()).toBe(true);
      expect(fs.readlinkSync(dest)).toBe(source);
    } finally {
      fs.rmSync(tmp, { recursive: true, force: true });
    }
  });

  test('guard allows ln when dest is an existing symlink (upgrade-in-place path)', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'gstack-setup-guard-'));
    try {
      const source = path.join(tmp, 'new-source');
      const oldSource = path.join(tmp, 'old-source');
      const dest = path.join(tmp, 'dest-symlink');
      fs.mkdirSync(source);
      fs.mkdirSync(oldSource);
      fs.symlinkSync(oldSource, dest);
      // Existing symlink: -L is true, so the guard does NOT trigger. ln -snf
      // should atomically retarget the symlink to the new source.
      const script = `
        set -e
        SOURCE_GSTACK_DIR='${source}'
        CLAUDE_GSTACK_LINK='${dest}'
        _SKIP_CLAUDE_REGISTER=0
        if [ -d "$CLAUDE_GSTACK_LINK" ] && [ ! -L "$CLAUDE_GSTACK_LINK" ]; then
          _EXISTING_REAL=$(cd "$CLAUDE_GSTACK_LINK" 2>/dev/null && pwd -P || echo "")
          if [ -n "$_EXISTING_REAL" ] && [ "$_EXISTING_REAL" != "$SOURCE_GSTACK_DIR" ]; then
            _SKIP_CLAUDE_REGISTER=1
          fi
        fi
        if [ "$_SKIP_CLAUDE_REGISTER" -eq 1 ]; then
          echo "SKIP"
        else
          ln -snf "$SOURCE_GSTACK_DIR" "$CLAUDE_GSTACK_LINK"
          echo "LINKED"
        fi
      `;
      const result = spawnSync('bash', ['-c', script], { encoding: 'utf-8' });
      expect(result.status).toBe(0);
      expect(result.stdout.trim()).toBe('LINKED');
      expect(fs.readlinkSync(dest)).toBe(source);
    } finally {
      fs.rmSync(tmp, { recursive: true, force: true });
    }
  });

  test('guard allows ln when dest is a real dir already pointing to source (self-rerun)', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'gstack-setup-guard-'));
    try {
      const source = path.join(tmp, 'source-worktree');
      fs.mkdirSync(source);
      // Mirror setup's SOURCE_GSTACK_DIR resolution (`pwd -P`) so the comparison
      // is fair on macOS where /tmp itself is a symlink to /private/tmp.
      const resolvedSource = fs.realpathSync(source);
      // Degenerate case: existing real dir IS the source.
      const dest = source;
      const script = `
        set -e
        SOURCE_GSTACK_DIR='${resolvedSource}'
        CLAUDE_GSTACK_LINK='${dest}'
        _SKIP_CLAUDE_REGISTER=0
        if [ -d "$CLAUDE_GSTACK_LINK" ] && [ ! -L "$CLAUDE_GSTACK_LINK" ]; then
          _EXISTING_REAL=$(cd "$CLAUDE_GSTACK_LINK" 2>/dev/null && pwd -P || echo "")
          if [ -n "$_EXISTING_REAL" ] && [ "$_EXISTING_REAL" != "$SOURCE_GSTACK_DIR" ]; then
            _SKIP_CLAUDE_REGISTER=1
          fi
        fi
        echo "skip=$_SKIP_CLAUDE_REGISTER"
      `;
      const result = spawnSync('bash', ['-c', script], { encoding: 'utf-8' });
      expect(result.status).toBe(0);
      expect(result.stdout.trim()).toBe('skip=0');
    } finally {
      fs.rmSync(tmp, { recursive: true, force: true });
    }
  });
});

// E2E: /setup-gbrain Path 4 with a bad bearer token via Agent SDK.
//
// Drives the skill against a stub HTTP MCP server that returns 401
// (auth-shape body). Asserts that the AUTH classifier hint shows up
// AND no MCP registration happens (no claude mcp add --transport http
// in the call log; no half-written CLAUDE.md block). This is the
// regression guard for the "verify failed → STOP" gate.
//
// Cost: ~$0.30-$0.50 per run. Gate-tier (EVALS=1 EVALS_TIER=gate).

import { describe, test, expect } from 'bun:test';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import * as http from 'http';
import { runAgentSdkTest, passThroughNonAskUserQuestion, resolveClaudeBinary } from './helpers/agent-sdk-runner';

// Periodic-tier (companion to skill-e2e-setup-gbrain-remote.test.ts).
// Deterministic gate coverage lives in setup-gbrain-path4-structure.test.ts.
const shouldRun = !!process.env.EVALS && process.env.EVALS_TIER === 'periodic';
const describeE2E = shouldRun ? describe : describe.skip;

function startStub401(): Promise<{ url: string; close: () => Promise<void> }> {
  return new Promise((resolve) => {
    const server = http.createServer((req, res) => {
      let body = '';
      req.on('data', (c) => (body += c));
      req.on('end', () => {
        res.statusCode = 401;
        res.setHeader('Content-Type', 'application/json');
        res.end(
          JSON.stringify({ error: 'unauthorized', error_description: 'invalid or expired auth token' })
        );
      });
    });
    server.listen(0, '127.0.0.1', () => {
      const addr = server.address();
      if (!addr || typeof addr === 'string') throw new Error('no address');
      resolve({
        url: `http://127.0.0.1:${addr.port}/mcp`,
        close: () => new Promise((r) => server.close(() => r())),
      });
    });
  });
}

function makeFakeClaude(fakeBinDir: string): string {
  const callLog = path.join(fakeBinDir, 'claude-calls.log');
  const script = `#!/bin/bash
echo "claude $@" >> "${callLog}"
case "$1 $2" in
  "mcp add") exit 0 ;;
  "mcp list") echo "no gbrain" ; exit 0 ;;
  "mcp remove") exit 0 ;;
  "mcp get") exit 1 ;;
esac
exit 0
`;
  fs.writeFileSync(path.join(fakeBinDir, 'claude'), script, { mode: 0o755 });
  return callLog;
}

describeE2E('/setup-gbrain Path 4 — bad token STOPs cleanly', () => {
  test('AUTH classifier fires, no MCP registration, no CLAUDE.md mutation', async () => {
    const stubServer = await startStub401();
    const gstackHome = fs.mkdtempSync(path.join(os.tmpdir(), 'setup-gbrain-bad-'));
    const fakeBinDir = fs.mkdtempSync(path.join(os.tmpdir(), 'setup-gbrain-bad-bin-'));
    const callLog = makeFakeClaude(fakeBinDir);

    const ORIGINAL_CLAUDE_MD = '# Test project\n\nSome existing content here.\n';
    fs.writeFileSync(path.join(gstackHome, 'CLAUDE.md'), ORIGINAL_CLAUDE_MD);

    const BAD_TOKEN = 'gbrain_BAD_TOKEN_67890_DELIBERATELY_INVALID';
    const askUserQuestions: Array<{ input: Record<string, unknown> }> = [];
    const binary = resolveClaudeBinary();

    const orig = {
      gstackHome: process.env.GSTACK_HOME,
      pathEnv: process.env.PATH,
      mcpToken: process.env.GBRAIN_MCP_TOKEN,
    };
    process.env.GSTACK_HOME = gstackHome;
    process.env.PATH = `${fakeBinDir}:${path.join(path.resolve(import.meta.dir, '..'), 'bin')}:${process.env.PATH ?? '/usr/bin:/bin:/opt/homebrew/bin'}`;
    process.env.GBRAIN_MCP_TOKEN = BAD_TOKEN;

    let modelTextOutput = '';

    try {
      const skillPath = path.resolve(import.meta.dir, '..', 'setup-gbrain', 'SKILL.md');
      const result = await runAgentSdkTest({
        systemPrompt: { type: 'preset', preset: 'claude_code' },
        userPrompt:
          `Read the skill file at ${skillPath} and follow Path 4 (Remote MCP) only. ` +
          `Use this MCP URL: ${stubServer.url}. ` +
          `The bearer token is already in the GBRAIN_MCP_TOKEN env var. ` +
          `If verify fails (Step 4c), follow the skill's STOP rule — surface the error and stop. ` +
          `Do NOT register the MCP if verify failed. ` +
          `Do NOT modify CLAUDE.md if verify failed.`,
        workingDirectory: gstackHome,
        maxTurns: 15,
        allowedTools: ['Read', 'Grep', 'Glob', 'Bash', 'Write', 'Edit'],
        ...(binary ? { pathToClaudeCodeExecutable: binary } : {}),
        canUseTool: async (toolName, input) => {
          if (toolName === 'AskUserQuestion') {
            askUserQuestions.push({ input });
            const q = (input.questions as Array<{
              question: string;
              options: Array<{ label: string }>;
            }>)[0];
            const decline = q.options.find((o) => /skip|decline|no/i.test(o.label)) ?? q.options[0]!;
            return {
              behavior: 'allow',
              updatedInput: { questions: input.questions, answers: { [q.question]: decline.label } },
            };
          }
          return passThroughNonAskUserQuestion(toolName, input);
        },
      });

      modelTextOutput = JSON.stringify(result);

      // Assertion 1: the AUTH classifier hint surfaced somewhere in the run.
      // The verify helper outputs `"error_class": "AUTH"` and the hint
      // "rotate token on the brain host" — at least one should be visible.
      const hintShown =
        /error_class.*AUTH/i.test(modelTextOutput) ||
        /rotate token/i.test(modelTextOutput) ||
        /AUTH.*HTTP 401/i.test(modelTextOutput);
      expect(hintShown).toBe(true);

      // Assertion 2: claude mcp add was NEVER called (verify failed → STOP).
      const calls = fs.existsSync(callLog) ? fs.readFileSync(callLog, 'utf-8') : '';
      expect(calls).not.toMatch(/mcp add.*--transport http/);

      // Assertion 3: CLAUDE.md is unchanged (no half-written block).
      const finalClaudeMd = fs.readFileSync(path.join(gstackHome, 'CLAUDE.md'), 'utf-8');
      expect(finalClaudeMd).toBe(ORIGINAL_CLAUDE_MD);

      // Assertion 4: the bad token never leaked to CLAUDE.md.
      expect(finalClaudeMd).not.toContain(BAD_TOKEN);
    } finally {
      if (orig.gstackHome === undefined) delete process.env.GSTACK_HOME; else process.env.GSTACK_HOME = orig.gstackHome;
      if (orig.pathEnv === undefined) delete process.env.PATH; else process.env.PATH = orig.pathEnv;
      if (orig.mcpToken === undefined) delete process.env.GBRAIN_MCP_TOKEN; else process.env.GBRAIN_MCP_TOKEN = orig.mcpToken;
      await stubServer.close();
      fs.rmSync(gstackHome, { recursive: true, force: true });
      fs.rmSync(fakeBinDir, { recursive: true, force: true });
    }
  }, 240_000);
});

import { describe, test, expect } from 'bun:test';
import { spawnSync } from 'child_process';
import * as path from 'path';
import * as fs from 'fs';
import * as os from 'os';

const ROOT = path.resolve(import.meta.dir, '..');
const SETUP_SCRIPT = path.join(ROOT, 'setup');

describe('setup: Apple Silicon codesign', () => {
  test('setup script contains codesign block for Darwin arm64', () => {
    const content = fs.readFileSync(SETUP_SCRIPT, 'utf-8');
    // Verify the codesign guard checks both Darwin and arm64
    expect(content).toContain('$(uname -s)" = "Darwin"');
    expect(content).toContain('$(uname -m)" = "arm64"');
    // Verify remove-then-resign two-step pattern
    expect(content).toContain('codesign --remove-signature');
    expect(content).toContain('codesign -s - -f');
  });

  test('codesign block covers all compiled binaries', () => {
    const content = fs.readFileSync(SETUP_SCRIPT, 'utf-8');
    // Extract the binaries from the codesign for-loop
    const forMatch = content.match(/for _bin in ([^;]+);/);
    expect(forMatch).toBeTruthy();
    const binaries = forMatch![1].trim().split(/\s+/);
    // All four compiled binaries from `bun run build` must be covered
    expect(binaries).toContain('browse/dist/browse');
    expect(binaries).toContain('browse/dist/find-browse');
    expect(binaries).toContain('design/dist/design');
    expect(binaries).toContain('bin/gstack-global-discover');
  });

  test('codesign block is inside the NEEDS_BUILD=1 branch', () => {
    const content = fs.readFileSync(SETUP_SCRIPT, 'utf-8');
    // The codesign block should appear after the build command and before the
    // `if [ ! -x "$BROWSE_BIN" ]` guard that checks the build succeeded. The
    // setup script invokes the build via `bun_cmd run build` (not literal
    // `bun run build`) so the wrapper can route through asdf/volta/etc;
    // matching the wrapped form keeps this test stable across that indirection.
    const buildIdx = content.indexOf('bun_cmd run build');
    const codesignIdx = content.indexOf('codesign --remove-signature');
    const browseCheckIdx = content.indexOf('gstack setup failed: browse binary missing');
    expect(buildIdx).toBeGreaterThan(-1);
    expect(codesignIdx).toBeGreaterThan(buildIdx);
    expect(browseCheckIdx).toBeGreaterThan(codesignIdx);
  });

  test('codesign block is idempotent (skips missing binaries)', () => {
    const content = fs.readFileSync(SETUP_SCRIPT, 'utf-8');
    // The loop must guard with a file-existence + executable check before codesigning
    expect(content).toContain('[ -f "$_bin_path" ] && [ -x "$_bin_path" ] || continue');
  });

  test('codesign failure is a warning, not a fatal error', () => {
    const content = fs.readFileSync(SETUP_SCRIPT, 'utf-8');
    // On codesign failure, log a warning but don't exit
    expect(content).toContain('warning: codesign failed for');
    // Should NOT have `set -e` causing exit on codesign failure
    // (the `|| true` after --remove-signature and the if-guard around -s - -f handle this)
    expect(content).toContain('codesign --remove-signature "$_bin_path" 2>/dev/null || true');
  });

  test('codesign shell snippet is syntactically valid', () => {
    // Extract the codesign block and validate it parses as bash
    const content = fs.readFileSync(SETUP_SCRIPT, 'utf-8');
    const match = content.match(
      /# macOS Apple Silicon: ad-hoc codesign[\s\S]*?done\n\s*fi/
    );
    expect(match).toBeTruthy();
    const snippet = match![0];
    // Wrap in a function to make it a complete script, then syntax-check
    const testScript = `#!/usr/bin/env bash\nset -e\n_test_fn() {\n${snippet}\n}\n`;
    const result = spawnSync('bash', ['-n', '-c', testScript], {
      stdio: ['pipe', 'pipe', 'pipe'],
      timeout: 5000,
    });
    expect(result.status).toBe(0);
  });
});

import { describe, test, expect } from 'bun:test';
import { spawnSync } from 'child_process';
import * as path from 'path';
import * as fs from 'fs';
import * as os from 'os';

const ROOT = path.resolve(import.meta.dir, '..');
const SETUP_SCRIPT = path.join(ROOT, 'setup');
const SETUP_SRC = fs.readFileSync(SETUP_SCRIPT, 'utf-8');

// Slice out the _link_or_copy helper body via awk-style anchors so the test is
// resilient to line-number drift.
function extractHelper(): string {
  const start = SETUP_SRC.indexOf('_link_or_copy() {');
  const end = SETUP_SRC.indexOf('\n}\n', start);
  if (start < 0 || end < 0) throw new Error('Could not locate _link_or_copy() in setup');
  return SETUP_SRC.slice(start, end + 2);
}

describe('setup: _link_or_copy invariant (D7)', () => {
  test('helper function is defined near the top of setup', () => {
    expect(SETUP_SRC).toContain('_link_or_copy() {');
    expect(SETUP_SRC).toContain('if [ "$IS_WINDOWS" -eq 1 ]; then');
  });

  test('zero raw `ln` calls outside the helper body and comments', () => {
    // Pull the helper body out of the source first so its internal `ln -snf`
    // (the Unix branch) is exempted from the invariant.
    const helper = extractHelper();
    const withoutHelper = SETUP_SRC.replace(helper, '');

    // Strip shell comments to allow prose mentions of `ln -snf` in docstrings.
    const lines = withoutHelper.split('\n');
    const offending: { lineNo: number; line: string }[] = [];
    lines.forEach((line, idx) => {
      const trimmed = line.trim();
      if (trimmed.startsWith('#')) return;
      // Match standalone `ln ` invocations (allow `ln` as a substring in
      // variable names like `linked`, `_LINK`).
      if (/(^|[\s;&|`])ln\s+-/.test(line)) {
        offending.push({ lineNo: idx + 1, line: line.trim() });
      }
    });
    expect(offending).toEqual([]);
  });

  test('Windows-copy note message exists in setup', () => {
    expect(SETUP_SRC).toContain('Windows install uses file copies');
    expect(SETUP_SRC).toContain('_print_windows_copy_note_once');
  });

  test('link_claude_skill_dirs calls the Windows note printer', () => {
    const fnStart = SETUP_SRC.indexOf('link_claude_skill_dirs() {');
    const fnEnd = SETUP_SRC.indexOf('\n}\n', fnStart);
    const fnBody = SETUP_SRC.slice(fnStart, fnEnd);
    expect(fnBody).toContain('_print_windows_copy_note_once');
  });
});

// Behavior matrix uses Unix `ln -snf` semantics in the IS_WINDOWS=0 cells.
// On Windows-without-Developer-Mode (e.g. GitHub's free `windows-latest`
// runner), `ln -snf` silently produces a file copy rather than a symlink —
// that's literally the bug this helper exists to work around. Skip the whole
// matrix on Windows; the static-invariant tests above already pin the helper
// shape that the Windows install relies on.
describe.skipIf(process.platform === 'win32')('setup: _link_or_copy helper — behavior matrix', () => {
  // Source the helper into a temp shell with IS_WINDOWS set and exercise
  // each cell of the file/dir × Windows/Unix matrix.
  function runHelper(
    isWindows: '0' | '1',
    srcKind: 'file' | 'dir',
  ): { ok: boolean; targetIsSymlink: boolean; targetExists: boolean; stderr: string } {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'gstack-helper-'));
    try {
      const src = path.join(tmp, 'source');
      const dst = path.join(tmp, 'dest');
      if (srcKind === 'file') {
        fs.writeFileSync(src, 'hello\n');
      } else {
        fs.mkdirSync(src);
        fs.writeFileSync(path.join(src, 'inner.txt'), 'hello\n');
      }
      const helper = extractHelper();
      // IS_WINDOWS must exist as a shell-readable var before sourcing.
      const script = `IS_WINDOWS=${isWindows}\n${helper}\n_link_or_copy "${src}" "${dst}"\n`;
      const result = spawnSync('bash', ['-c', script], {
        encoding: 'utf-8',
        timeout: 5000,
      });
      const lst = fs.lstatSync(dst, { throwIfNoEntry: false });
      return {
        ok: result.status === 0,
        targetIsSymlink: lst?.isSymbolicLink() ?? false,
        targetExists: lst !== undefined,
        stderr: result.stderr,
      };
    } finally {
      fs.rmSync(tmp, { recursive: true, force: true });
    }
  }

  test('IS_WINDOWS=0 + file → symlink (existing Unix behavior)', () => {
    const r = runHelper('0', 'file');
    expect(r.ok).toBe(true);
    expect(r.targetExists).toBe(true);
    expect(r.targetIsSymlink).toBe(true);
  });

  test('IS_WINDOWS=0 + dir → symlink', () => {
    const r = runHelper('0', 'dir');
    expect(r.ok).toBe(true);
    expect(r.targetIsSymlink).toBe(true);
  });

  test('IS_WINDOWS=1 + file → regular file copy (no symlink)', () => {
    const r = runHelper('1', 'file');
    expect(r.ok).toBe(true);
    expect(r.targetExists).toBe(true);
    expect(r.targetIsSymlink).toBe(false);
  });

  test('IS_WINDOWS=1 + dir → real directory copy', () => {
    const r = runHelper('1', 'dir');
    expect(r.ok).toBe(true);
    expect(r.targetExists).toBe(true);
    expect(r.targetIsSymlink).toBe(false);
  });
});

